function body_json():array{$raw=file_get_contents('php://input');$d=json_decode($raw?:'{}',true);return is_array($d)?$d:[];}
function csrf():void{$provided=(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'');if(!hash_equals(WebSecurity::csrfToken(),$provided))json_out(['ok'=>false,'error'=>'Invalid request token.'],403);}
function safe_hex(string $v,int $len):bool{return (bool)preg_match('/^[a-f0-9]{'.$len.'}$/',$v);}
$action=(string)($_GET['action']??'');
